/**
 * SignGraph — the predication site: the small category SignCells generate.
 *
 * A site is a finite set of cells (as triples) together with specialization
 * morphisms between predicates. Its base category has two sorts of object —
 * entities (the terms in subject and object position) and predicates — and is
 * generated by the cell moves: converse (s,p,o) → (o,p,s), the subject and
 * object projections onto (s,p,s) and (o,p,o), and specialization, which
 * refines only the predicate coordinate: a morphism from a general predicate
 * to a specialized one (RDFS subPropertyOf, read general → specialized).
 * Everything valued over cells — fibers, presheaves, the sheaf on the foam —
 * is valued over this base.
 *
 * Specialization transports evidence: a telling for (s, q, o), q specializing
 * p, tells (s, p, o) for (RDFS entailment rule rdfs7); a telling against
 * (s, p, o) tells (s, q, o) against. `transportRules` states these as SignChain
 * rules over the site's cells, for SignCraft to settle.
 *
 * Terms are opaque values compared by SignCell coincidence (canonical bytes).
 * Evidence is not part of a site: a site is where values can be, not what they are.
 */
import { admitCell, cell, coincidenceKey, coincides, retainedCarrier, triple, tripleKey } from "@red-cup-engineering/signcell/cell";
import { rule } from "@red-cup-engineering/signchain/rules";
import { createGraph, reachable } from "@red-cup-engineering/metrologic/models/graphs/directed-multigraph";

// Distinct values by coincidence, first occurrence kept, in one pass over canonical-byte keys
// (comparing every value with every kept one was quadratic in the number of cells).
const uniqueBy = (values, keyOf) => {
  const seen = new Map();
  for (const value of values) {
    const key = keyOf(value);
    if (!seen.has(key)) seen.set(key, value);
  }
  return Object.freeze([...seen.values()]);
};

/** Inert finite source records: reject accessors, extra fields and inherited
 * declarations before a caller's executable properties can affect a site.
 * SignCell remains the owner of nested coordinate and evidence admission.
 */
const sourceRecord = (value, role) => {
  if (value === null || typeof value !== "object" || Array.isArray(value) ||
      ![Object.prototype, null].includes(Object.getPrototypeOf(value)))
    throw new TypeError(`signgraph site: ${role} must be a plain source record`);
  return Object.getOwnPropertyDescriptors(value);
};
const dataField = (descriptors, name, role) => {
  const slot = descriptors[name];
  if (!slot || !slot.enumerable || !Object.hasOwn(slot, "value"))
    throw new TypeError(`signgraph site: ${role}.${name} must be inert own data`);
  return slot.value;
};
const exactFields = (descriptors, required, optional = []) => {
  const names = Reflect.ownKeys(descriptors);
  return names.every(name => typeof name === "string" &&
    [...required, ...optional].includes(name)) &&
    required.every(name => Object.hasOwn(descriptors, name)) &&
    names.length >= required.length;
};
const sourceList = (value, role) => {
  if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype ||
      value.length > 16384)
    throw new TypeError(`signgraph site: ${role} must be a bounded plain source array`);
  const fields = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(fields).length !== value.length + 1)
    throw new TypeError(`signgraph site: ${role} must be dense and undecorated`);
  return Array.from({length: value.length}, (_, index) =>
    dataField(fields, String(index), role));
};
const sourceTriple = value => {
  const fields = sourceRecord(value, "cell");
  const names = ["subject", "predicate", "object"];
  const hasEvidence = ["for", "against", "value"].some(name => Object.hasOwn(fields, name));
  if (!exactFields(fields, hasEvidence ? [...names, "for", "against"] : names,
      hasEvidence ? ["value"] : []))
    throw new TypeError("signgraph site: a source cell must be an exact triple or evidence-bearing SignCell");
  const terms = Object.fromEntries(names.map(name => [name, dataField(fields, name, "cell")]));
  if (!hasEvidence) return triple(terms);
  const evidence = {
    for: sourceList(dataField(fields, "for", "cell"), "cell.for"),
    against: sourceList(dataField(fields, "against", "cell"), "cell.against"),
    ...(Object.hasOwn(fields, "value") ? {value: dataField(fields, "value", "cell")} : {}),
  };
  return triple(admitCell({...terms, ...evidence}));
};

/**
 * Read the ORIGINAL ordered incidences shared by sites, relation graphs and
 * oriented flow networks. This uses the site's existing exact source Triple /
 * SignCell admission, but deliberately does NOT deduplicate triples: repeated
 * source positions remain separate graph edges even when their semantic
 * cell addresses coincide. The resulting detached triples have NO evidential
 * force; source occurrence histories live with their original owner.
 */
export function sourceIncidenceTriples(values) {
  return Object.freeze(sourceList(values, "incidence cells").map(sourceTriple));
}

/** A specialization morphism: general predicate to specialized predicate.
 * Preserve the original presentation at the constructor (including the first
 * source representative); site() performs detached admission at its boundary.
 */
export const specializationMorphism = (specialized, general) =>
  Object.freeze({ kind: "signgraph.specialization", domain: general, codomain: specialized });
export const isSpecializationMorphism = value => {
  if (value === null || typeof value !== "object" || Array.isArray(value) ||
      ![Object.prototype, null].includes(Object.getPrototypeOf(value))) return false;
  const fields = Object.getOwnPropertyDescriptors(value);
  return exactFields(fields, ["kind", "domain", "codomain"]) &&
    ["kind", "domain", "codomain"].every(name =>
      fields[name].enumerable && Object.hasOwn(fields[name], "value")) &&
    fields.kind.value === "signgraph.specialization";
};

/** The distinct entity terms (subjects and objects) of a list of cells. */
export const entitiesOf = (cells) => uniqueBy(cells.flatMap((value) => [value.subject, value.object]), coincidenceKey);
/** The distinct predicate terms of a list of cells. */
export const predicatesOf = (cells) => uniqueBy(cells.map((value) => value.predicate), coincidenceKey);

function baseCategory(cells, entities, predicates, specializations) {
  const node = (value) => Object.freeze([value.subject, value.predicate, value.object]);
  return Object.freeze({
    kind: "signgraph.base",
    objects: Object.freeze([...entities.map((term) => Object.freeze({ sort: "entity", term })), ...predicates.map((term) => Object.freeze({ sort: "predicate", term }))]),
    specialization: Object.freeze([...specializations]),
    converse: Object.freeze(cells.map((value) => Object.freeze({ domain: node(value), codomain: Object.freeze([value.object, value.predicate, value.subject]) }))),
    subjectProjection: Object.freeze(cells.map((value) => Object.freeze({ domain: node(value), codomain: value.subject }))),
    objectProjection: Object.freeze(cells.map((value) => Object.freeze({ domain: node(value), codomain: value.object }))),
  });
}

/** A site over the exact finite source SignCells/triples and specializations.
 * The site projects EXTENSIONAL triples, not independent source evidence.
 * A caller's getter cannot select a generator or change its source position.
 */
export function site(witnesses, specializations = []) {
  const all = [...sourceList(witnesses, "witnesses"), ...sourceList(specializations, "specializations")];
  const originalCells = [], originalMorphisms = [];
  for (const value of all) {
    if (isSpecializationMorphism(value)) {
      const fields = sourceRecord(value, "specialization");
      originalMorphisms.push(retainedCarrier(specializationMorphism(
        dataField(fields, "codomain", "specialization"),
        dataField(fields, "domain", "specialization"))));
    } else {
      originalCells.push(sourceTriple(value));
    }
  }
  const cells = uniqueBy(originalCells, tripleKey);
  const morphisms = Object.freeze(originalMorphisms);
  const entities = entitiesOf(cells), predicates = predicatesOf(cells);
  return Object.freeze({ kind: "signgraph.site", cells, entities, predicates, specializations: morphisms, base: baseCategory(cells, entities, predicates, morphisms) });
}

/** Every cell E × Π × E over the given entities and predicates. */
export const generatedCells = (entities, predicates) => Object.freeze(entities.flatMap((subject) => predicates.flatMap((predicate) => entities.map((object) => triple(cell(subject, predicate, object))))));

/** The site an utterance (token, claim) generates: E = {token}, Π = {claim}, so its one cell is (token, claim, token). */
export const utteranceSite = (token, claim) => site(generatedCells([token], [claim]));

/** A site's generators, its stored presentation: cells and specializations only. */
export const presentSite = (value) => Object.freeze({ kind: "signgraph.site", cells: value.cells, specializations: value.specializations });
/** The full site back from its generators. */
export const freeSite = (generators) => site(generators.cells, generators.specializations);

/** The base with its specialization relation transitively closed.
 * Metrologic supplies the original finite directed reachability algorithm;
 * SignGraph only supplies its *semantic* predicate presentations and the
 * existing morphism carrier. No second graph search or content hash lives
 * here. Reachability is positive-length: a reflexive specialization appears
 * only where the source has a loop/cycle, not by inventing the identity edge.
 */
export function closeSpecialization(base) {
  // Public closure is a receiving boundary, too: a direct caller need not
  // have entered through site(). Copy only inert own source fields, so spread
  // cannot execute a getter after the graph has already been traversed.
  const fields = sourceRecord(base, "base");
  const original = [];
  for (const key of Reflect.ownKeys(fields)) {
    if (typeof key !== "string")
      throw new TypeError("signgraph site: base keys must be string source data");
    original.push([key, dataField(fields, key, "base")]);
  }
  const admittedBase = Object.fromEntries(original);
  const declarations = sourceList(dataField(fields, "specialization", "base"),
    "base.specialization").map(edge => {
      if (!isSpecializationMorphism(edge))
        throw new TypeError("signgraph site: invalid source specialization");
      const positions = sourceRecord(edge, "specialization");
      return [dataField(positions, "domain", "specialization"),
        dataField(positions, "codomain", "specialization")];
    });
  const graph = createGraph();
  const terms = new Map();
  const edges = [];
  const seen = new Set();
  const keyOf = (value) => {
    const id = coincidenceKey(value);
    if (!terms.has(id)) terms.set(id, value);
    return id;
  };
  const include = (from, to) => {
    const pair = JSON.stringify([from, to]);
    if (seen.has(pair)) return;
    seen.add(pair);
    edges.push(Object.freeze({
      kind: "signgraph.specialization",
      domain: terms.get(from),
      codomain: terms.get(to),
    }));
  };
  for (const [domain, codomain] of declarations) {
    const from = keyOf(domain), to = keyOf(codomain);
    graph.addEdge({ from, to, kind: "specializes" });
    include(from, to);
  }
  // Preserve admitted direct edges first. Append only the genuinely derived
  // pairs in original node and reachable order; no O(E^3+) replay over pairs.
  for (const { id: from } of graph.nodes())
    for (const to of reachable(graph, from, { kind: "specializes" }))
      include(from, to);
  return Object.freeze({ ...admittedBase, specialization: Object.freeze(edges) });
}

/** Cohere a site: its cells, and the residue with specialization closed. */
export const cohere = (value) => Object.freeze({ kind: "signgraph.coherence", saturated: value.cells, residue: Object.freeze({ ...value, base: closeSpecialization(value.base) }) });

/** The ordered predicate pairs no (closed) specialization relates. */
export function unrelatedPairs(value) {
  const closed = closeSpecialization(value.base);
  const related = (domain, codomain) => closed.specialization.some((edge) => coincides(edge.domain, domain) && coincides(edge.codomain, codomain));
  const edges = [];
  for (const domain of value.predicates) for (const codomain of value.predicates) if (!related(domain, codomain)) edges.push(Object.freeze({ domain, codomain }));
  return Object.freeze({ kind: "signgraph.unrelatedPairs", edges: Object.freeze(edges) });
}

/** The rules by which a site's (closed) specializations transport evidence between its cells:
 *  for-evidence up from the specialized predicate to the general one, against-evidence down. */
export function transportRules(value) {
  const closed = closeSpecialization(value.base);
  const has = (at) => value.cells.some((other) => coincides(triple(other), triple(at)));
  const rules = [];
  for (const edge of closed.specialization) {
    for (const at of value.cells) {
      if (!coincides(at.predicate, edge.codomain)) continue;
      const general = triple(cell(at.subject, edge.domain, at.object));
      if (!has(general)) continue;
      rules.push(rule(`specialization-for:${JSON.stringify([at.subject, edge.codomain, edge.domain, at.object])}`, [{ cell: at, atLeast: "potential" }], { cell: general, reading: "potential" }));
      rules.push(rule(`specialization-against:${JSON.stringify([at.subject, edge.domain, edge.codomain, at.object])}`, [{ cell: general, atLeast: "active" }], { cell: at, reading: "active" }));
    }
  }
  return Object.freeze(rules);
}

/** The JSON Schema of a site's generators. */
export const siteGeneratorsSchema = Object.freeze({
  $id: "https://schemas.561.group/signgraph/site-generators.schema.json",
  type: "object",
  required: ["kind", "cells", "specializations"],
  properties: {
    kind: { const: "signgraph.site" },
    cells: { type: "array", maxItems: 16384, items: { type: "object", required: ["subject", "predicate", "object"], properties: { subject: {}, predicate: {}, object: {} }, additionalProperties: false } },
    specializations: { type: "array", maxItems: 16384, items: { type: "object", required: ["kind", "domain", "codomain"], properties: { kind: { const: "signgraph.specialization" }, domain: {}, codomain: {} }, additionalProperties: false } },
  },
  additionalProperties: false,
  title: "SiteGenerators",
  description: "The cells and specializations a predication site is freely constructed from.",
});
